#include "Челтәр_Стәк.h"
extern int32_t 되돌림전문만들기(int32_t,int32_t,int32_t), 되돌림전문묶기(int32_t,int32_t,int32_t);
extern int32_t 되돌림전문보내기(int32_t,int32_t,int32_t,int32_t), 되돌림전문받기(int32_t,int32_t);
extern int32_t 되돌림전문접속번호(int32_t), 되돌림전문주소(int32_t), 되돌림전문상대(int32_t), 되돌림전문닫기(int32_t);
extern int32_t 자바전문넣기(int32_t,int32_t),자바전문얻기(int32_t);
extern int32_t 되돌림흐름만들기(void),되돌림흐름묶기(int32_t,int32_t,int32_t),되돌림흐름듣기(int32_t,int32_t);
extern int32_t 되돌림흐름연결(int32_t,int32_t,int32_t),되돌림흐름연결받기(int32_t),되돌림흐름읽기(int32_t,int32_t),되돌림흐름쓰기(int32_t,int32_t);
extern int32_t 되돌림흐름접속번호(int32_t),되돌림흐름상대(int32_t),되돌림흐름닫기(int32_t);
static int 외부연결[24];
static int 임의주소[24], 양쪽수신창구[24], 전문외부상대[8], 묶인주소[8];
static int 외부번호(int файл_дескриптор) { return файл_дескриптор>=32 && файл_дескриптор<56 ? 외부연결[файл_дескриптор-32]-1 : -1; }
static int өстәү_СМС(int файл_дескриптор,int TYPE_категория) {
    if(файл_дескриптор<32||файл_дескриптор>=56)return -9;int 이전=외부번호(файл_дескриптор);if(이전>=0)return 이전;
    int элемент_COUNT=통신끝점만들기(TYPE_категория);if(элемент_COUNT>=0)외부연결[файл_дескриптор-32]=элемент_COUNT+1;return элемент_COUNT;
}
int32_t 자바전문만들기(int32_t 첫째값,int32_t SECOND_VALUE,int32_t символ_коды){return 되돌림전문만들기(첫째값,SECOND_VALUE,символ_коды);}
int32_t 자바전문묶기(int32_t файл_дескриптор,int32_t Интернеттагы_адрес,int32_t 접속번호){
    if(Интернеттагы_адрес==0x7f000001)return 되돌림전문묶기(файл_дескриптор,Интернеттагы_адрес,접속번호);
    if(Интернеттагы_адрес!=0&&Интернеттагы_адрес!=망상태읽기(0,0))return -99;
    int 반환값=되돌림전문묶기(файл_дескриптор,0,접속번호);if(반환값<0)return 반환값;
    int элемент_COUNT=өстәү_СМС(файл_дескриптор,2);if(элемент_COUNT<0)return элемент_COUNT;반환값=망주소묶기(элемент_COUNT,망상태읽기(0,0),되돌림전문접속번호(файл_дескриптор));if(!반환값)묶인주소[файл_дескриптор-32]=Интернеттагы_адрес;return 반환값;
}
int32_t 자바전문보내기(int32_t файл_дескриптор,int32_t Интернеттагы_адрес,int32_t 접속번호,int32_t үлчәмен_үзгәртү){
    if(Интернеттагы_адрес==0x7f000001)return 되돌림전문보내기(файл_дескриптор,Интернеттагы_адрес,접속번호,үлчәмен_үзгәртү);
    if(үлчәмен_үзгәртү<0||үлчәмен_үзгәртү>512)return -90;if(접속번호<1||접속번호>65535)return -22;
    if(되돌림전문접속번호(файл_дескриптор)<0)return -9;
    if(되돌림전문주소(файл_дескриптор)==0x7f000001)return -101;
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0){int 반환값=0;if(되돌림전문접속번호(файл_дескриптор)==0)반환값=되돌림전문묶기(файл_дескриптор,0,0);if(반환값<0)return 반환값;элемент_COUNT=өстәү_СМС(файл_дескриптор,2);if(элемент_COUNT<0)return элемент_COUNT;반환값=망주소묶기(элемент_COUNT,망상태읽기(0,0),되돌림전문접속번호(файл_дескриптор));if(반환값<0)return 반환값;}
    unsigned char мәгълүмат[512];for(int 순번=0;순번<үлчәмен_үзгәртү;순번++)мәгълүмат[순번]=자바전문얻기(순번);return 전문보내기(элемент_COUNT,мәгълүмат,үлчәмен_үзгәртү,Интернеттагы_адрес,접속번호);
}
int32_t 자바전문받기(int32_t файл_дескриптор,int32_t үлчәмен_үзгәртү){
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0)return 되돌림전문받기(файл_дескриптор,үлчәмен_үзгәртү);if(үлчәмен_үзгәртү<0||үлчәмен_үзгәртү>512)return -22;
    int локаль=되돌림전문받기(файл_дескриптор,үлчәмен_үзгәртү);if(локаль!=-11){전문외부상대[файл_дескриптор-32]=0;return локаль;}
    unsigned char мәгълүмат[512];int 반환값=전문받기(элемент_COUNT,мәгълүмат,үлчәмен_үзгәртү);if(반환값>=0)전문외부상대[файл_дескриптор-32]=1;for(int 순번=0;순번<반환값;순번++)자바전문넣기(순번,мәгълүмат[순번]);return 반환값;
}
int32_t 자바전문접속번호(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);return элемент_COUNT<0?되돌림전문접속번호(файл_дескриптор):(int32_t)통신접속번호(элемент_COUNT);}
int32_t 자바전문주소(int32_t файл_дескриптор){return 외부번호(файл_дескриптор)<0?되돌림전문주소(файл_дескриптор):묶인주소[файл_дескриптор-32];}
int32_t 자바전문상대(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);return элемент_COUNT<0||!전문외부상대[файл_дескриптор-32]?되돌림전문상대(файл_дескриптор):(int32_t)상대접속번호(элемент_COUNT);}
int32_t 자바전문원격주소(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);return элемент_COUNT<0||!전문외부상대[файл_дескриптор-32]?0x7f000001:(int32_t)상대통신주소(элемент_COUNT);}
int32_t 자바전문닫기(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT>=0){чик_Челтәр(элемент_COUNT);외부연결[файл_дескриптор-32]=0;}if(файл_дескриптор>=32&&файл_дескриптор<40)전문외부상대[файл_дескриптор-32]=묶인주소[файл_дескриптор-32]=0;return 되돌림전문닫기(файл_дескриптор);}
int32_t 자바흐름만들기(void){return 되돌림흐름만들기();}
int32_t 자바흐름묶기(int32_t файл_дескриптор,int32_t Интернеттагы_адрес,int32_t 접속번호){
    if(Интернеттагы_адрес==0||Интернеттагы_адрес==0x7f000001){int 반환값=되돌림흐름묶기(файл_дескриптор,Интернеттагы_адрес,접속번호);if(!반환값)임의주소[файл_дескриптор-32]=Интернеттагы_адрес==0;return 반환값;}
    if(Интернеттагы_адрес!=망상태읽기(0,0))return -99;int 반환값=되돌림흐름묶기(файл_дескриптор,0,접속번호);if(반환값<0)return 반환값;
    int элемент_COUNT=өстәү_СМС(файл_дескриптор,1);return элемент_COUNT<0?элемент_COUNT:망주소묶기(элемент_COUNT,Интернеттагы_адрес,되돌림흐름접속번호(файл_дескриптор));
}
int32_t 자바흐름듣기(int32_t файл_дескриптор,int32_t 연결대기한도){
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0){int 반환값=되돌림흐름듣기(файл_дескриптор,연결대기한도);if(반환값<0||!임의주소[файл_дескриптор-32])return 반환값;
        элемент_COUNT=өстәү_СМС(файл_дескриптор,1);if(элемент_COUNT<0)return элемент_COUNT;반환값=망주소묶기(элемент_COUNT,망상태읽기(0,0),되돌림흐름접속번호(файл_дескриптор));if(반환값<0)return 반환값;양쪽수신창구[файл_дескриптор-32]=1;
    }return 연결대기한도<1?-22:연결기다리기(элемент_COUNT);
}
int32_t 자바흐름연결(int32_t файл_дескриптор,int32_t Интернеттагы_адрес,int32_t 접속번호){
    if(Интернеттагы_адрес==0x7f000001 && 외부번호(файл_дескриптор)<0)return 되돌림흐름연결(файл_дескриптор,Интернеттагы_адрес,접속번호);
    if(되돌림흐름접속번호(файл_дескриптор)<0)return -9;int элемент_COUNT=өстәү_СМС(файл_дескриптор,1);return элемент_COUNT<0?элемент_COUNT:망연결하기(элемент_COUNT,Интернеттагы_адрес,접속번호);
}
int32_t 자바흐름연결받기(int32_t файл_дескриптор){
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0)return 되돌림흐름연결받기(файл_дескриптор);
    if(양쪽수신창구[файл_дескриптор-32]){int локаль=되돌림흐름연결받기(файл_дескриптор);if(локаль!=-11)return локаль;}
    int тиңдәш_VALUE=망연결받기(элемент_COUNT);if(тиңдәш_VALUE<0)return тиңдәш_VALUE;
    int максат_кыйммәт=되돌림흐름만들기();if(максат_кыйммәт<0){чик_Челтәр(тиңдәш_VALUE);return максат_кыйммәт;}외부연결[максат_кыйммәт-32]=тиңдәш_VALUE+1;return максат_кыйммәт;
}
int32_t 자바흐름읽기(int32_t файл_дескриптор,int32_t үлчәмен_үзгәртү){
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0)return 되돌림흐름읽기(файл_дескриптор,үлчәмен_үзгәртү);if(үлчәмен_үзгәртү<0||үлчәмен_үзгәртү>512)return -22;
    unsigned char мәгълүмат[512];int 반환값=통신읽기(элемент_COUNT,мәгълүмат,үлчәмен_үзгәртү);for(int 순번=0;순번<반환값;순번++)자바전문넣기(순번,мәгълүмат[순번]);return 반환값;
}
int32_t 자바흐름쓰기(int32_t файл_дескриптор,int32_t үлчәмен_үзгәртү){
    int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT<0)return 되돌림흐름쓰기(файл_дескриптор,үлчәмен_үзгәртү);if(үлчәмен_үзгәртү<0||үлчәмен_үзгәртү>512)return -22;
    unsigned char мәгълүмат[512];for(int 순번=0;순번<үлчәмен_үзгәртү;순번++)мәгълүмат[순번]=자바전문얻기(순번);return 통신쓰기(элемент_COUNT,мәгълүмат,үлчәмен_үзгәртү);
}
int32_t 자바흐름접속번호(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);return элемент_COUNT<0?되돌림흐름접속번호(файл_дескриптор):(int32_t)통신접속번호(элемент_COUNT);}
int32_t 자바흐름상대(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);return элемент_COUNT<0?되돌림흐름상대(файл_дескриптор):(int32_t)상대접속번호(элемент_COUNT);}
int32_t 자바흐름주소(int32_t файл_дескриптор){return 외부번호(файл_дескриптор)<0?0x7f000001:양쪽수신창구[файл_дескриптор-32]?0:망상태읽기(0,0);}
int32_t 자바흐름닫기(int32_t файл_дескриптор){int элемент_COUNT=외부번호(файл_дескриптор);if(элемент_COUNT>=0){чик_Челтәр(элемент_COUNT);외부연결[файл_дескриптор-32]=0;}if(файл_дескриптор>=40&&файл_дескриптор<56)임의주소[файл_дескриптор-32]=양쪽수신창구[файл_дескриптор-32]=0;return 되돌림흐름닫기(файл_дескриптор);}
